"""Render a self-contained interactive research report, with no CDN requests."""

from __future__ import annotations

import json
from pathlib import Path


def render_report(report: dict, path: Path) -> None:
    data = json.dumps(report, ensure_ascii=False, allow_nan=False).replace("<", "\\u003c")
    path.write_text(TEMPLATE.replace("__REPORT_DATA__", data), encoding="utf-8")


